<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableCodeVO;

trait TemplateVariableCodeAccessor {
  private TemplateVariableCodeVO $_code;
  public function getCode(): string
  {
    return $this->_code->value();
  }
  public function code(): TemplateVariableCodeVO
  {
    return $this->_code;
  }
  public function isCodeChanged(?self $original = null): bool
  {
  return !$this->_code->equals( $original?->_code );  }
  public function withCode(TemplateVariableCodeVO|string $code): self
  {
    $copy = clone $this;
    $copy->_code = TemplateVariableCodeVO::from( $code );
    return $copy;
  }
}